  "inlineSchema": "// prisma/schema.prisma\n// Multi-Event Invitation SaaS Platform\n// Database: PostgreSQL (Supabase)\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\")\n  directUrl = env(\"DIRECT_URL\")\n}\n\n// ─────────────────────────────────────────────────────────\n// USERS\n// Synced from Clerk via webhook (POST /api/webhooks/clerk)\n// ─────────────────────────────────────────────────────────\nmodel User {\n  id        String   @id // Clerk user ID\n  email     String   @unique\n  name      String?\n  imageUrl  String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  events        Event[]\n  subscriptions Subscription[]\n\n  @@map(\"users\")\n}\n\n// ─────────────────────────────────────────────────────────\n// EVENTS\n// Each user can create multiple events of any type\n// ─────────────────────────────────────────────────────────\nmodel Event {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  name         String\n  slug         String    @unique // URL-safe, e.g. \"gabby-esther-wedding\"\n  eventType    EventType @default(WEDDING)\n  date         DateTime\n  time         String? // e.g. \"2:00 PM\"\n  venue        String\n  description  String?   @db.Text\n  dressCode    String?\n  rsvpDeadline DateTime?\n\n  // Organizer\n  organizerName  String?\n  organizerPhone String?\n  organizerEmail String?\n\n  // Branding\n  logoUrl        String?\n  coverUrl       String?\n  primaryColor   String  @default(\"#0A2810\")\n  secondaryColor String  @default(\"#B8860B\")\n  accentColor    String  @default(\"#F8F4E3\")\n\n  // Template\n  templateId String?\n  template   Template? @relation(fields: [templateId], references: [id])\n\n  // Settings\n  isPublished  Boolean @default(false)\n  requirePhoto Boolean @default(true)\n  maxGuests    Int?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  guests   Guest[]\n  checkins Checkin[]\n\n  @@index([userId])\n  @@index([slug])\n  @@map(\"events\")\n}\n\nenum EventType {\n  WEDDING\n  BIRTHDAY\n  CONFERENCE\n  CONCERT\n  CHURCH\n  SEMINAR\n  VIP_PARTY\n  BURIAL\n  PRIVATE_DINNER\n  OTHER\n}\n\n// ─────────────────────────────────────────────────────────\n// GUESTS\n// Guests belong to a specific event\n// ─────────────────────────────────────────────────────────\nmodel Guest {\n  id      String @id @default(cuid())\n  eventId String\n  event   Event  @relation(fields: [eventId], references: [id], onDelete: Cascade)\n\n  name  String\n  phone String // Normalized (0XXXXXXXXXX format)\n  email String?\n\n  // Status\n  invited     Boolean      @default(true)\n  importedAt  DateTime     @default(now())\n  importedVia ImportSource @default(MANUAL)\n\n  rsvp    Rsvp?\n  checkin Checkin?\n\n  @@unique([eventId, phone]) // No duplicate phones per event\n  @@index([eventId])\n  @@index([phone])\n  @@map(\"guests\")\n}\n\nenum ImportSource {\n  MANUAL\n  BULK_TEXT\n  CSV\n  EXCEL\n  DOCX\n  TXT\n}\n\n// ─────────────────────────────────────────────────────────\n// RSVPs\n// One RSVP per guest (one-to-one with Guest)\n// ─────────────────────────────────────────────────────────\nmodel Rsvp {\n  id      String @id @default(cuid())\n  guestId String @unique\n  guest   Guest  @relation(fields: [guestId], references: [id], onDelete: Cascade)\n\n  status     RsvpStatus @default(PENDING)\n  attendance Boolean? // true = yes, false = no\n\n  // Generated on RSVP confirmation\n  uniqueCode String? @unique // e.g. \"INV-A3X7P2\"\n  seatNumber Int?\n  cardUrl    String? // Cloudinary URL of generated card\n\n  // Guest provided info\n  email      String?\n  photoUrl   String? // Cloudinary URL of guest photo\n  guestPhoto String? @db.Text // Base64 for card generation (temporary)\n\n  // Metadata\n  rsvpedAt  DateTime?\n  updatedAt DateTime  @updatedAt\n  createdAt DateTime  @default(now())\n\n  @@index([uniqueCode])\n  @@map(\"rsvps\")\n}\n\nenum RsvpStatus {\n  PENDING\n  CONFIRMED\n  DECLINED\n}\n\n// ─────────────────────────────────────────────────────────\n// CHECKINS\n// QR scan check-in at the event venue\n// ─────────────────────────────────────────────────────────\nmodel Checkin {\n  id      String @id @default(cuid())\n  eventId String\n  event   Event  @relation(fields: [eventId], references: [id], onDelete: Cascade)\n  guestId String @unique\n  guest   Guest  @relation(fields: [guestId], references: [id], onDelete: Cascade)\n\n  checkedInAt DateTime @default(now())\n  checkedInBy String? // Staff member / device ID\n  notes       String?\n\n  @@index([eventId])\n  @@map(\"checkins\")\n}\n\n// ─────────────────────────────────────────────────────────\n// TEMPLATES\n// Reusable IV card templates\n// ─────────────────────────────────────────────────────────\nmodel Template {\n  id           String    @id @default(cuid())\n  name         String\n  description  String?\n  category     EventType @default(WEDDING)\n  thumbnailUrl String?\n  isPublic     Boolean   @default(true) // System templates visible to all\n  createdBy    String? // User ID if custom template\n\n  // Design config (JSON)\n  config Json @default(\"{}\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  events Event[]\n\n  @@map(\"templates\")\n}\n\n// ─────────────────────────────────────────────────────────\n// SUBSCRIPTIONS\n// Plan management per user\n// ─────────────────────────────────────────────────────────\nmodel Subscription {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  plan   SubscriptionPlan @default(FREE)\n  status SubStatus        @default(ACTIVE)\n\n  // Billing\n  stripeCustomerId     String?\n  stripeSubscriptionId String?\n  stripePriceId        String?\n  currentPeriodStart   DateTime?\n  currentPeriodEnd     DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId])\n  @@map(\"subscriptions\")\n}\n\nenum SubscriptionPlan {\n  FREE // 1 event, 50 guests\n  BASIC // 5 events, 500 guests, custom branding\n  PREMIUM // Unlimited, all features\n}\n\nenum SubStatus {\n  ACTIVE\n  CANCELLED\n  PAST_DUE\n  TRIALING\n}\n",
